// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation.select;

import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.query.explanation.GenericPlanNode;

/**
 * Centralised reader for the two string explain metrics the behavioural suite observes: the execution path (which
 * strategy tag ran at a node, several tags joined by {@code |}) and the strategy declines. Tests go through this class
 * so a metric key rename is a one-line change.
 */
public final class ExplainPath {

	/** Metric key under which the native engine records the chosen strategy tag(s) at a plan node. */
	public static final String EXECUTION_PATH = "nativeExecutionPath";

	/** Metric key under which the native engine records strategies that declined at a plan node. */
	public static final String STRATEGY_DECLINES = "nativeStrategyDeclines";

	private ExplainPath() {
	}

	/** Every strategy tag recorded anywhere in the tree, in plan order, de-duplicated. */
	public static Set<String> executionPaths(GenericPlanNode root) {
		Set<String> paths = new LinkedHashSet<>();
		collect(root, EXECUTION_PATH, paths);
		return paths;
	}

	/** Every decline entry recorded anywhere in the tree, in plan order, de-duplicated. */
	public static Set<String> declines(GenericPlanNode root) {
		Set<String> declines = new LinkedHashSet<>();
		collect(root, STRATEGY_DECLINES, declines);
		return declines;
	}

	/** Execution path per plan node, keyed by the path of node types from the root, for nodes that have one. */
	public static Map<String, String> executionPathsByNode(GenericPlanNode root) {
		Map<String, String> byNode = new LinkedHashMap<>();
		collectByNode(root, "", byNode);
		return byNode;
	}

	private static void collect(GenericPlanNode node, String metric, Set<String> out) {
		if (node == null) {
			return;
		}
		String value = node.getStringMetricActual(metric);
		if (value != null) {
			for (String tag : value.split("\\|")) {
				out.add(tag.trim());
			}
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collect(child, metric, out));
		}
	}

	private static void collectByNode(GenericPlanNode node, String parentPath, Map<String, String> out) {
		if (node == null) {
			return;
		}
		String path = parentPath.isEmpty() ? node.getType() : parentPath + "/" + node.getType();
		String value = node.getStringMetricActual(EXECUTION_PATH);
		if (value != null) {
			// several nodes can share a type path; keep them distinct with an ordinal suffix
			String key = path;
			int ordinal = 1;
			while (out.containsKey(key)) {
				key = path + "#" + (++ordinal);
			}
			out.put(key, value);
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collectByNode(child, path, out));
		}
	}
}
